insert into public.products (id, sku, category, name_en, name_bn, description_en, description_bn, price, stock, unit, weight_kg, care_level, aesthetic_tags, supplier_id, illustration, image_url, active, plant, pot, hardware) values
  ('plt-0001', 'PLT-0001', 'plant', 'Money plant (golden pothos)', 'মানি প্ল্যান্ট', 'Thrives in bright shade and forgives missed waterings; trails beautifully from a shelf.', 'উজ্জ্বল ছায়ায় ভালো থাকে, পানি দিতে ভুলে গেলেও টিকে যায়; তাক থেকে সুন্দরভাবে ঝুলে পড়ে।', 220, 60, 'pot', 1, 'easy', array['tropical', 'minimal']::text[], 'sup-dhk-nursery-1', '{"form":"trailing","color":"#4c9a2a","accent":"#e3e86b"}'::jsonb, null, true, '{"species":"Epipremnum aureum","min_sun_hours":1,"max_sun_hours":4,"water_every_days":5,"mature_height_cm":180,"mature_spread_cm":50,"indoor_ok":true,"outdoor_ok":true,"pet_safe":false,"monsoon_tolerant":true,"heat_tolerant":true,"coastal_ok":true,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":6}'::jsonb, null, null),
  ('plt-0002', 'PLT-0002', 'plant', 'Snake plant', 'স্নেক প্ল্যান্ট', 'Nearly indestructible in low light with little water — just keep it out of monsoon downpours.', 'কম আলো ও অল্প পানিতেই প্রায় অক্ষয়; শুধু বর্ষার টানা বৃষ্টি থেকে দূরে রাখুন।', 550, 45, 'pot', 2.5, 'easy', array['modern', 'minimal']::text[], 'sup-dhk-nursery-1', '{"form":"upright","color":"#3d6b35","accent":"#c9d46a"}'::jsonb, null, true, '{"species":"Dracaena trifasciata","min_sun_hours":1,"max_sun_hours":6,"water_every_days":14,"mature_height_cm":75,"mature_spread_cm":30,"indoor_ok":true,"outdoor_ok":true,"pet_safe":false,"monsoon_tolerant":false,"heat_tolerant":true,"coastal_ok":true,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":8}'::jsonb, null, null),
  ('plt-0003', 'PLT-0003', 'plant', 'ZZ plant', 'জেডজেড প্ল্যান্ট', 'Glossy leaves that handle dim corners and weeks of neglect.', 'চকচকে পাতা; অন্ধকার কোণ আর কয়েক সপ্তাহের অযত্নেও টিকে থাকে।', 850, 25, 'pot', 2.5, 'easy', array['modern', 'minimal']::text[], 'sup-dhk-nursery-4', '{"form":"upright","color":"#2f6b2f","accent":"#4f9a3f"}'::jsonb, null, true, '{"species":"Zamioculcas zamiifolia","min_sun_hours":1,"max_sun_hours":4,"water_every_days":14,"mature_height_cm":60,"mature_spread_cm":50,"indoor_ok":true,"outdoor_ok":true,"pet_safe":false,"monsoon_tolerant":false,"heat_tolerant":true,"coastal_ok":false,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":8}'::jsonb, null, null),
