  ('plt-0006', 'PLT-0006', 'plant', 'Peace lily', 'পিস লিলি', 'Droops when thirsty and perks up after a drink; white blooms even in shade.', 'পানির অভাবে পাতা নেতিয়ে পড়ে, পানি দিলেই সতেজ হয়; ছায়াতেও সাদা ফুল দেয়।', 450, 30, 'pot', 2, 'easy', array['minimal', 'modern']::text[], 'sup-dhk-nursery-1', '{"form":"flowering","color":"#2e7d32","accent":"#f5f5f0"}'::jsonb, null, true, '{"species":"Spathiphyllum wallisii","min_sun_hours":1,"max_sun_hours":3,"water_every_days":3,"mature_height_cm":60,"mature_spread_cm":50,"indoor_ok":true,"outdoor_ok":true,"pet_safe":false,"monsoon_tolerant":true,"heat_tolerant":false,"coastal_ok":false,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":8}'::jsonb, null, null),
  ('plt-0007', 'PLT-0007', 'plant', 'Aglaonema (red)', 'অ্যাগলোনেমা (লাল)', 'Pink-and-green leaves that stay colourful even in low light.', 'গোলাপি-সবুজ পাতা কম আলোতেও রঙিন থাকে।', 650, 28, 'pot', 2, 'easy', array['colorful', 'modern']::text[], 'sup-dhk-nursery-2', '{"form":"bushy","color":"#3d7a3a","accent":"#e0475b"}'::jsonb, null, true, '{"species":"Aglaonema ''Siam Aurora''","min_sun_hours":1,"max_sun_hours":3,"water_every_days":5,"mature_height_cm":50,"mature_spread_cm":45,"indoor_ok":true,"outdoor_ok":true,"pet_safe":false,"monsoon_tolerant":true,"heat_tolerant":true,"coastal_ok":false,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":8}'::jsonb, null, null),
  ('plt-0008', 'PLT-0008', 'plant', 'Spider plant', 'স্পাইডার প্ল্যান্ট', 'Pet-safe and fast-growing; sends out baby plantlets you can repot.', 'পোষা প্রাণীর জন্য নিরাপদ ও দ্রুত বাড়ে; ছোট চারা দেয় যা আলাদা টবে লাগানো যায়।', 200, 50, 'pot', 0.9, 'easy', array['boho', 'minimal']::text[], 'sup-dhk-nursery-3', '{"form":"trailing","color":"#6aa84f","accent":"#f0f3d0"}'::jsonb, null, true, '{"species":"Chlorophytum comosum","min_sun_hours":2,"max_sun_hours":5,"water_every_days":4,"mature_height_cm":30,"mature_spread_cm":50,"indoor_ok":true,"outdoor_ok":true,"pet_safe":true,"monsoon_tolerant":true,"heat_tolerant":false,"coastal_ok":true,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":6}'::jsonb, null, null),
  ('plt-0009', 'PLT-0009', 'plant', 'Boston fern', 'বোস্টন ফার্ন', 'Lush, pet-safe fern for hanging baskets; keep it moist and out of hot sun.', 'ঝুলন্ত টবের জন্য ঘন, পোষা প্রাণীর জন্য নিরাপদ ফার্ন; মাটি ভেজা রাখুন ও কড়া রোদ থেকে দূরে রাখুন।', 350, 35, 'pot', 1.5, 'easy', array['boho', 'tropical']::text[], 'sup-dhk-nursery-2', '{"form":"bushy","color":"#4f9d3a","accent":"#8cc63f"}'::jsonb, null, true, '{"species":"Nephrolepis exaltata","min_sun_hours":1,"max_sun_hours":3,"water_every_days":2,"mature_height_cm":50,"mature_spread_cm":70,"indoor_ok":true,"outdoor_ok":true,"pet_safe":true,"monsoon_tolerant":true,"heat_tolerant":false,"coastal_ok":false,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":8}'::jsonb, null, null),
  ('plt-0010', 'PLT-0010', 'plant', 'Bird''s nest fern', 'বার্ডস নেস্ট ফার্ন', 'Wavy, glossy fronds that love humid monsoon air and bright shade.', 'ঢেউ খেলানো চকচকে পাতা; বর্ষার আর্দ্র বাতাস আর উজ্জ্বল ছায়া পছন্দ করে।', 550, 15, 'pot', 2, 'easy', array['tropical', 'modern']::text[], 'sup-ctg-nursery-2', '{"form":"upright","color":"#5cae3c","accent":"#3c7a28"}'::jsonb, null, true, '{"species":"Asplenium nidus","min_sun_hours":1,"max_sun_hours":3,"water_every_days":4,"mature_height_cm":60,"mature_spread_cm":60,"indoor_ok":true,"outdoor_ok":true,"pet_safe":true,"monsoon_tolerant":true,"heat_tolerant":false,"coastal_ok":false,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":8}'::jsonb, null, null),
  ('plt-0011', 'PLT-0011', 'plant', 'Rubber plant', 'রাবার প্ল্যান্ট', 'Bold glossy leaves; tolerates heat and a few hours of direct sun.', 'বড় চকচকে পাতা; গরম আর কয়েক ঘণ্টার সরাসরি রোদ সহ্য করে।', 750, 22, 'pot', 4, 'easy', array['modern', 'minimal']::text[], 'sup-dhk-nursery-4', '{"form":"upright","color":"#1f4d2b","accent":"#7a2e3a"}'::jsonb, null, true, '{"species":"Ficus elastica","min_sun_hours":2,"max_sun_hours":6,"water_every_days":6,"mature_height_cm":150,"mature_spread_cm":60,"indoor_ok":true,"outdoor_ok":true,"pet_safe":false,"monsoon_tolerant":true,"heat_tolerant":true,"coastal_ok":true,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":10}'::jsonb, null, null),
  ('plt-0012', 'PLT-0012', 'plant', 'Syngonium (arrowhead plant)', 'সিঙ্গোনিয়াম', 'Arrow-shaped leaves in pink or lime; happy in bright shade.', 'তীরের মতো গোলাপি বা হালকা সবুজ পাতা; উজ্জ্বল ছায়ায় ভালো থাকে।', 250, 40, 'pot', 1, 'easy', array['colorful', 'tropical']::text[], 'sup-dhk-nursery-1', '{"form":"trailing","color":"#7cb342","accent":"#f2b8c6"}'::jsonb, null, true, '{"species":"Syngonium podophyllum","min_sun_hours":1,"max_sun_hours":4,"water_every_days":4,"mature_height_cm":40,"mature_spread_cm":40,"indoor_ok":true,"outdoor_ok":true,"pet_safe":false,"monsoon_tolerant":true,"heat_tolerant":true,"coastal_ok":false,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":6}'::jsonb, null, null),
  ('plt-0013', 'PLT-0013', 'plant', 'Heartleaf philodendron', 'ফিলোডেনড্রন', 'Heart-shaped trailing leaves for shelves and hanging pots in low light.', 'হৃদয় আকৃতির লতানো পাতা; কম আলোয় তাক বা ঝুলন্ত টবের জন্য ভালো।', 350, 32, 'pot', 1.2, 'easy', array['tropical', 'boho']::text[], 'sup-dhk-nursery-1', '{"form":"trailing","color":"#3e8e41","accent":"#a5d66b"}'::jsonb, null, true, '{"species":"Philodendron hederaceum","min_sun_hours":1,"max_sun_hours":4,"water_every_days":5,"mature_height_cm":150,"mature_spread_cm":40,"indoor_ok":true,"outdoor_ok":true,"pet_safe":false,"monsoon_tolerant":true,"heat_tolerant":true,"coastal_ok":false,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":6}'::jsonb, null, null),
  ('plt-0014', 'PLT-0014', 'plant', 'Monstera', 'মনস্টেরা', 'Statement split leaves; give it a moss pole and bright indirect light.', 'কাটা কাটা বড় পাতার আকর্ষণীয় গাছ; মস পোল ও উজ্জ্বল পরোক্ষ আলো দিন।', 2200, 10, 'pot', 9, 'moderate', array['tropical', 'modern']::text[], 'sup-dhk-nursery-4', '{"form":"upright","color":"#2b6e35","accent":"#4c9a50"}'::jsonb, null, true, '{"species":"Monstera deliciosa","min_sun_hours":2,"max_sun_hours":5,"water_every_days":6,"mature_height_cm":150,"mature_spread_cm":100,"indoor_ok":true,"outdoor_ok":true,"pet_safe":false,"monsoon_tolerant":true,"heat_tolerant":true,"coastal_ok":false,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":14}'::jsonb, null, null),
  ('plt-0015', 'PLT-0015', 'plant', 'Croton', 'ক্রোটন (পাতাবাহার)', 'Red-and-yellow leaves that grow brighter with more sun; loves Bangladeshi heat.', 'লাল-হলুদ পাতা রোদ বেশি পেলে আরও উজ্জ্বল হয়; বাংলাদেশের গরমে খুব ভালো থাকে।', 300, 38, 'pot', 2.5, 'easy', array['colorful', 'traditional']::text[], 'sup-ctg-nursery-1', '{"form":"bushy","color":"#4a7a2a","accent":"#f2a900"}'::jsonb, null, true, '{"species":"Codiaeum variegatum","min_sun_hours":4,"max_sun_hours":8,"water_every_days":3,"mature_height_cm":90,"mature_spread_cm":60,"indoor_ok":true,"outdoor_ok":true,"pet_safe":false,"monsoon_tolerant":true,"heat_tolerant":true,"coastal_ok":true,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":10}'::jsonb, null, null),
  ('plt-0016', 'PLT-0016', 'plant', 'Dracaena (dragon tree)', 'ড্রাসিনা', 'Slim, spiky and architectural; let the soil dry between waterings.', 'সরু, খাড়া পাতার আধুনিক গড়ন; দুই বার পানি দেওয়ার মাঝে মাটি শুকাতে দিন।', 600, 20, 'pot', 3, 'easy', array['modern', 'minimal']::text[], 'sup-dhk-nursery-2', '{"form":"upright","color":"#3a6b2f","accent":"#b0343c"}'::jsonb, null, true, '{"species":"Dracaena marginata","min_sun_hours":2,"max_sun_hours":5,"water_every_days":7,"mature_height_cm":150,"mature_spread_cm":50,"indoor_ok":true,"outdoor_ok":true,"pet_safe":false,"monsoon_tolerant":false,"heat_tolerant":true,"coastal_ok":true,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":10}'::jsonb, null, null),
  ('plt-0017', 'PLT-0017', 'plant', 'Lucky bamboo (3-tier)', 'লাকি ব্যাম্বু', 'Grows indoors in water or soil; change the water every week.', 'ঘরের ভেতরে পানি বা মাটিতে বাড়ে; প্রতি সপ্তাহে পানি বদলে দিন।', 450, 30, 'pot', 1.5, 'easy', array['minimal', 'traditional']::text[], 'sup-dhk-nursery-3', '{"form":"upright","color":"#6fbf4a","accent":"#c8a24a"}'::jsonb, null, true, '{"species":"Dracaena sanderiana","min_sun_hours":1,"max_sun_hours":3,"water_every_days":7,"mature_height_cm":60,"mature_spread_cm":25,"indoor_ok":true,"outdoor_ok":false,"pet_safe":false,"monsoon_tolerant":false,"heat_tolerant":false,"coastal_ok":false,"edible":false,"fragrant":false,"seasons":["all"],"pot_size_in":6}'::jsonb, null, null),
