  ('acc-0013', 'ACC-0013', 'accessory', 'Pressure sprayer (2 L)', 'প্রেশার স্প্রেয়ার (২ লিটার)', 'Pump-up mister for foliage, neem oil and liquid feed.', 'পাতায় পানি, নিম তেল ও তরল সার ছিটানোর পাম্প স্প্রেয়ার।', 550, 30, 'piece', 0.6, 'easy', array['minimal']::text[], 'sup-dhk-accessories-1', '{"form":"tool","color":"#f9a825","accent":"#333333"}'::jsonb, null, true, null, null, null),
  ('acc-0014', 'ACC-0014', 'accessory', 'Drainage trays 10" (set of 4)', 'পানি ধরার ট্রে ১০ ইঞ্চি (৪টির সেট)', 'Catches run-off so the balcony floor — and the neighbours below — stay dry.', 'চুইয়ে পড়া পানি ধরে রাখে, তাই বারান্দার মেঝে ও নিচের প্রতিবেশী শুকনো থাকে।', 240, 60, 'set', 0.4, 'easy', array['minimal']::text[], 'sup-dhk-accessories-1', '{"form":"tool","color":"#3a3a3a"}'::jsonb, null, true, null, null, null),
  ('acc-0015', 'ACC-0015', 'accessory', 'Plant stand (3-tier metal)', 'প্ল্যান্ট স্ট্যান্ড (৩ তাক, ধাতব)', 'Ladder stand that holds 6–9 pots in under half a square metre.', 'মই আকৃতির স্ট্যান্ড, আধা বর্গমিটারের কম জায়গায় ৬–৯টি টব রাখা যায়।', 2200, 10, 'piece', 6, 'easy', array['modern', 'minimal']::text[], 'sup-dhk-accessories-1', '{"form":"tool","color":"#2f2f2f"}'::jsonb, null, true, null, null, null)
