insert into public.bundles (id, slug, name_en, name_bn, description_en, description_bn, discount_pct, min_sun_hours, max_sun_hours, illustration) values
  ('bnd-low-light-herbs', 'low-light-herb-starter', 'Low-light herb starter', 'কম আলোর ভেষজ স্টার্টার', 'Mint and thankuni — two herbs that still crop on a balcony with only 3–5 hours of sun.', 'পুদিনা ও থানকুনি — দিনে মাত্র ৩–৫ ঘণ্টা রোদ পাওয়া বারান্দাতেও ফলন দেয় এমন দুটি ভেষজ।', 10, 3, 5, '{"form":"herb","color":"#4caf50","accent":"#a5d6a7"}'::jsonb),
  ('bnd-monsoon-balcony', 'monsoon-tolerant-balcony', 'Monsoon-tolerant balcony', 'বর্ষা-সহনশীল বারান্দা', 'Foliage that shrugs off months of rain and humidity, in fast-draining clay pots.', 'দ্রুত পানি বের হওয়া মাটির টবে এমন গাছ, যা মাসের পর মাস বৃষ্টি ও আর্দ্রতায় দিব্যি থাকে।', 10, 2, 4, '{"form":"palm","color":"#5aa13a","accent":"#3fa9f5"}'::jsonb),
  ('bnd-kitchen-herb-railing', 'kitchen-herb-railing', 'Kitchen herb railing', 'রান্নাঘরের ভেষজ রেলিং', 'Tulsi, basil and green chili in two railing planters — fresh flavour without using floor space.', 'দুটি রেলিং প্ল্যান্টারে তুলসী, বেসিল ও কাঁচা মরিচ — মেঝের জায়গা ছাড়াই তাজা স্বাদ।', 8, 6, 8, '{"form":"planter-long","color":"#6b8e23","accent":"#d32f2f"}'::jsonb),
  ('bnd-fragrant-evening', 'fragrant-evening-balcony', 'Fragrant evening balcony', 'সুগন্ধি সন্ধ্যার বারান্দা', 'Beli, rajanigandha and kamini under warm string lights — a balcony that smells best after dark.', 'উষ্ণ আলোর নিচে বেলি, রজনীগন্ধা ও কামিনী — সন্ধ্যার পর সুগন্ধে ভরে ওঠা বারান্দা।', 12, 6, 8, '{"form":"bushy","color":"#3f7f2f","accent":"#fdfdf5"}'::jsonb),
  ('bnd-pet-safe-corner', 'pet-safe-green-corner', 'Pet-safe green corner', 'পোষা-নিরাপদ সবুজ কোণ', 'Only ASPCA-listed non-toxic plants, for a shaded corner shared with cats or dogs.', 'বিড়াল বা কুকুরের সাথে ভাগ করা ছায়াময় কোণের জন্য শুধু বিষমুক্ত হিসেবে স্বীকৃত গাছ।', 10, 2, 3, '{"form":"palm","color":"#3f8a3a","accent":"#c66b8f"}'::jsonb),
  ('bnd-sunny-flower-burst', 'sunny-flower-burst', 'Sunny flower burst', 'রোদেলা ফুলের উৎসব', 'Heat-proof colour for a full-sun balcony: joba, bougainvillea, nayantara, zinnia and portulaca.', 'পূর্ণ রোদের বারান্দার জন্য গরম-সহনশীল রঙ: জবা, বাগানবিলাস, নয়নতারা, জিনিয়া ও টাইম ফুল।', 12, 6, 10, '{"form":"flowering","color":"#2f6e2f","accent":"#d6247f"}'::jsonb),
  ('bnd-vertical-wall', 'tiny-balcony-vertical-wall', 'Tiny-balcony vertical wall', 'ছোট বারান্দার ভার্টিক্যাল দেয়াল', 'Twelve trailing plants on a wall frame — a full green wall that uses almost no floor space.', 'দেয়ালের ফ্রেমে বারোটি লতানো গাছ — মেঝের জায়গা প্রায় না নিয়েই পুরো সবুজ দেয়াল।', 15, 2, 4, '{"form":"trellis","color":"#3a3a3a","accent":"#4c9a2a"}'::jsonb),
  ('bnd-winter-colour', 'winter-colour-pack', 'Winter colour pack', 'শীতের রঙিন ফুলের প্যাক', 'Chandramallika, dahlia, petunia and gada for a bright November–February balcony.', 'নভেম্বর–ফেব্রুয়ারির উজ্জ্বল বারান্দার জন্য চন্দ্রমল্লিকা, ডালিয়া, পিটুনিয়া ও গাঁদা।', 10, 6, 8, '{"form":"flowering","color":"#3a6e30","accent":"#f7d21e"}'::jsonb)
